import BoardFeature from './BoardFeature';
import PinCapability from './PinCapability';

export default {
    name: 'MRT SmartCoding',
    fqbn: 'arduino:avr:uno',
    icon: 'data:image/png;base64,',
    pins: Array.from({ length: 20 }, (_, i) => {
        if (i === 0 || i === 1) return null;

        let label = '';
        let capabilities = 0;
        let analog = -1;
        if (i < 14) {
            label = `D${i}`;
            capabilities |= PinCapability.DIGITAL | PinCapability.INPUT | PinCapability.OUTPUT;
        } else {
            analog = i - 14;
            label = `A${analog}`;
            capabilities |= PinCapability.ANALOG | PinCapability.INPUT | PinCapability.OUTPUT;
        }

        if (i === 3 || i === 5 || i === 6 || i === 9 || i === 10 || i === 11) {
            label = `~${label}`;
            capabilities |= PinCapability.PWM;
        }

        if (i === 10 || i === 11) {
            capabilities |= PinCapability.SERVO;
        }

        return {
            index: i,
            analog: analog,
            label: label,
            capabilities: capabilities
        };
    }).filter(Boolean),
    features: BoardFeature.I2C | BoardFeature.SERIAL
};
